class Solution {long cross(int[] a,int[] b,int[] c){return ((long)b[0]-a[0])*((long)c[1]-a[1])-((long)b[1]-a[1])*((long)c[0]-a[0]);}public int[][] solve(int[][] points){Arrays.sort(points,(a,b)->a[0]!=b[0]?Integer.compare(a[0],b[0]):Integer.compare(a[1],b[1]));ArrayList<int[]> p=new ArrayList<>();for(int[] v:points)if(p.isEmpty()||!Arrays.equals(p.get(p.size()-1),v))p.add(v);if(p.size()<2)return p.toArray(new int[0][]);ArrayList<int[]> lower=new ArrayList<>(),upper=new ArrayList<>();for(int[] v:p){while(lower.size()>1&&cross(lower.get(lower.size()-2),lower.get(lower.size()-1),v)<=0)lower.remove(lower.size()-1);lower.add(v);}for(int i=p.size()-1;i>=0;i--){int[] v=p.get(i);while(upper.size()>1&&cross(upper.get(upper.size()-2),upper.get(upper.size()-1),v)<=0)upper.remove(upper.size()-1);upper.add(v);}lower.remove(lower.size()-1);upper.remove(upper.size()-1);lower.addAll(upper);return lower.toArray(new int[0][]);}}